function demoMain(idx,label){
  var total=[1000000,5000000,250000][idx%3];var chunk=100000;var chunks=Math.ceil(total/chunk);
  var sum=0;for(var i=0;i<chunks;i++){sum+=(Math.min((i+1)*chunk,total)-i*chunk);}
  return "["+label+"] streamed "+total+" rows in "+chunks+" chunks, processed="+sum+" rows, peak-mem=chunk-size only";
}

